}

export interface ChordSliceViewFactors {
  sliceIndex: number; // 0 to sliceCount-1 (0 = bottom edge, sliceCount-1 = top edge)
  normalizedChordPosition: number; // 0.05 to 0.95
  heightAboveGroundM: number;
